def MEM(icon='controller', wipe=None, fade=None, only=False, **k):
    b = dict(k='mem', v=1, icon=icon, smudgeOnly=only, **k)
    if wipe: b['wipeA'] = wipe
    if fade: b['fadeA'] = fade
    return b
